using FallenForest.Core;using FallenForest.UI;using UnityEngine;namespace FallenForest.Documents{[RequireComponent(typeof(Collider))]public sealed class DocumentPickup:MonoBehaviour{[SerializeField]private AudioClip pickupSound;[SerializeField]private GameObject subtleOutline;[SerializeField]private int documentSlot=-1;private bool collected;public int DocumentSlot=>documentSlot;public void Configure(int slot){documentSlot=slot;if(SaveSystem.IsDocumentCollected(slot))gameObject.SetActive(false);}private void OnTriggerEnter(Collider other){if(collected||documentSlot<0||GameProgress.Instance==null)return;FallenForest.Player.PlayerMotor player=other.GetComponentInParent<FallenForest.Player.PlayerMotor>();if(player==null)return;if(GameProgress.Instance.CollectDocument(documentSlot)){collected=true;SaveSystem.SavePlayerPosition(player.transform.position);if(pickupSound!=null)AudioSource.PlayClipAtPoint(pickupSound,transform.position,.85f);HUDController.Instance?.ShowDocumentCount(GameProgress.Instance.DocumentsCollected);gameObject.SetActive(false);}}}}
